using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var scenes = EditorBuildSettings.scenes;
        if (scenes.Length == 0)
        {
            result.Log("No scenes in build settings.");
            return;
        }
        result.Log("Scenes in build:");
        foreach (var s in scenes)
        {
            result.Log("  enabled=" + s.enabled + " path=" + s.path);
        }
        result.Log("Active scene: " + SceneManager.GetActiveScene().name);
        result.Log("Active scene path: " + SceneManager.GetActiveScene().path);
        var active = SceneManager.GetActiveScene();
        result.Log("Active isLoaded: " + active.isLoaded);
        var roots = active.GetRootGameObjects();
        result.Log("Root count: " + roots.Length);
        foreach (var r in roots)
        {
            var cn = r.GetComponents<Component>().Length;
            result.Log("  root: " + r.name + " comps=" + cn);
        }
        var hud = GameObject.Find("HudRoot");
        if (hud == null)
        {
            result.Log("HudRoot not found in active scene.");
        }
        else
        {
            result.Log("HudRoot present in active scene: " + hud.activeInHierarchy);
            foreach (var c in hud.GetComponents<Component>())
            {
                result.Log("    comp: " + (c == null ? "null" : c.GetType().Name));
            }
        }
    }
}
